new file mode 100644
index 0000000..105bcc1
--- /dev/null
+++ b/source/standalone/boundary-stream.ts
@@ -0,0 +1,16 @@
+import type {Readable} from 'node:stream';
+import is from '@sindresorhus/is';
+
+type BoundaryStream = {
+	getBoundary: (() => string) | string;
+	getLength: (callback: (error: Error | null, length: number) => void) => void; // eslint-disable-line @typescript-eslint/ban-types
+} & Readable;
+
+export default function isBoundaryStream(body: unknown): body is BoundaryStream {
+	if (!is.nodeStream(body)) {
+		return false;
+	}
+
+	const {getBoundary} = body as BoundaryStream;
+	return is.function(getBoundary) || is.string(getBoundary);
+}
diff --git a/test/boundary-stream.ts b/test/boundary-stream.ts
new file mode 100644
index 0000000..b92d0ce
--- /dev/null
+++ b/test/boundary-stream.ts
@@ -0,0 +1,44 @@
+import {Readable, PassThrough} from 'node:stream';
+import test from 'ava';
+import FormData from 'form-data';
+import isBoundaryStream from '../source/standalone/boundary-stream.js';
+
+const withBoundary = (getBoundary: unknown) => Object.assign(new PassThrough(), {getBoundary});
+
+test('accepts a stream with a callable getBoundary', t => {
+	t.true(isBoundaryStream(withBoundary(() => 'boundary')));
+	t.true(isBoundaryStream(new FormData()));
+});
+
+test('accepts a stream with a string getBoundary', t => {
+	t.true(isBoundaryStream(withBoundary('boundary')));
+	t.true(isBoundaryStream(withBoundary('')));
+});
+
+test('rejects a stream without a usable getBoundary', t => {
+	t.false(isBoundaryStream(new PassThrough()));
+	t.false(isBoundaryStream(Readable.from([])));
+	t.false(isBoundaryStream(withBoundary(undefined)));
+	t.false(isBoundaryStream(withBoundary(null)));
+	t.false(isBoundaryStream(withBoundary(123)));
+	t.false(isBoundaryStream(withBoundary({})));
+});
+
+test('requires a node stream', t => {
+	t.false(isBoundaryStream({getBoundary: () => 'boundary'}));
+	t.false(isBoundaryStream({getBoundary: 'boundary'}));
+	t.false(isBoundaryStream(undefined));
+	t.false(isBoundaryStream(null));
+	t.false(isBoundaryStream(''));
+	t.false(isBoundaryStream({}));
+});
+
+test('does not read getBoundary from non-streams', t => {
+	const body = {
+		get getBoundary() {
+			throw new Error('should not be accessed');
+		},
+	};
+
+	t.false(isBoundaryStream(body));
+});
